makeClosure = function(proto, upvalues, environment)
    local closure
    closure = function(...)
        local currentEnvironment = environment
        if hostGetfenv then currentEnvironment = hostGetfenv(closure) end
        if proto.precondition and not proto.precondition(currentEnvironment) then return end
        if proto.native then return proto.native(currentEnvironment, ...) end
        return execute(proto, upvalues, currentEnvironment, ...)
    end
    if hostSetfenv then hostSetfenv(closure, environment) end
    return closure
end

