-- Translate rendered text only. Canonical option values, flags and callbacks remain intact.
local function installLocalization(pool,env,dictionary)
    local state={language="zh-TW",bindings={},records={},connections={},libraries={},active=true}
    local previous=env.__MoonSecUI
    if type(previous)=="table" and type(previous.stop)=="function" then pcall(previous.stop) end
    local function canonical(value)
        if value=="English" or value=="en" then return "en" end
        if value=="繁體中文" or value=="zh-TW" then return "zh-TW" end
    end
    state.language=canonical(env.__MoonSecUILanguage) or "zh-TW"
    if type(env.readfile)=="function" then
        local ok,value=pcall(env.readfile,"0xseanlee-ui-language.txt")
        if ok then state.language=canonical(value) or state.language end
    end
    local extras={
        ["Info"]={"Info","資訊"},
        ["Creator"]={"Creator","創作者"},
        ["Copy Discord Link"]={"Copy Discord Link","複製 Discord 連結"},
        ["Join the community using the link below."]={"Join the community using the link below.","透過下方連結加入社群。"},
        ["by 0xseanlee"]={"by 0xseanlee","作者：0xseanlee"},
        ["Interface"]={"Interface","介面"},
        ["Choose your interface language."]={"Choose your interface language.","選擇介面顯示語言。"},
        ["None"]={"None","無"},["Select"]={"Select","選擇"},
        ["Not Spawned"]={"Not Spawned","尚未生成"},["Spawned"]={"Spawned","已生成"},
        ["Not Found"]={"Not Found","未找到"},["Found"]={"Found","已找到"},
        ["Searching..."]={"Searching...","搜尋中…"},["Waiting..."]={"Waiting...","等待中…"},
        ["Normal Fruit Stock"]={"Normal Fruit Stock","普通果實庫存"},
        ["Advance Fruit Stock"]={"Advanced Fruit Stock","進階果實庫存"},
        ["- Không có trái nào."]={"- No fruit available.","－目前沒有果實。"},
        ["Search"]={"Search","搜尋"},["Search..."]={"Search...","搜尋…"},
        ["Cancel"]={"Cancel","取消"},["Confirm"]={"Confirm","確認"},["Close"]={"Close","關閉"},
    }
    for key,value in pairs(extras) do dictionary[key]=value end
    function state.translate(value)
        if type(value)~="string" then return value end
        local entry=dictionary[value]
        if entry then return entry[state.language=="en" and 1 or 2] end
        local result=value
        for _,pair in ipairs({{"Advance Fruit Stock","Advanced Fruit Stock","進階果實庫存"},
            {"Normal Fruit Stock","Normal Fruit Stock","普通果實庫存"},
            {"Không có trái nào.","No fruit available.","目前沒有果實。"}}) do
            local replacement=pair[state.language=="en" and 2 or 3]
            result=result:gsub(pair[1]:gsub("(%W)","%%%1"),function() return replacement end)
        end
        return result
    end
    local function render(record)
        record.rendered=state.translate(record.raw)
        record.changing=true
        pcall(function() record.object[record.property]=record.rendered end)
        record.changing=false
    end
    function state.bind(object)
        if state.bindings[object] then return end
        local property="Text"
        local ok,raw=pcall(function()
            if object:IsA("TextBox") then property="PlaceholderText";return object.PlaceholderText end
            if object:IsA("TextLabel") or object:IsA("TextButton") then return object.Text end
        end)
        if not ok or type(raw)~="string" then return end
        local record={object=object,raw=raw,property=property}
        state.bindings[object]=record;state.records[#state.records+1]=record
        local connected,connection=pcall(function()
            return object:GetPropertyChangedSignal(property):Connect(function()
                if not state.active or record.changing then return end
                local read,value=pcall(function() return object[property] end)
                if read and value~=record.rendered then record.raw=value;render(record) end
            end)
        end)
        if connected then state.connections[#state.connections+1]=connection end
        render(record)
    end
    function state.scan(lib)
        local instances=rawget(lib,"Instances")
        if type(instances)~="table" then return end
        local cursor=state.libraries[lib] or 0
        if #instances<cursor then cursor=0 end
        for i=cursor+1,#instances do
            local entry=instances[i]
            if type(entry)=="table" and entry.Instance then state.bind(entry.Instance) end
        end
        state.libraries[lib]=#instances
    end
    function state.setLanguage(value)
        local language=canonical(value)
        if not language then return false end
        state.language=language;env.__MoonSecUILanguage=language
        for lib in pairs(state.libraries) do state.scan(lib) end
        for _,record in ipairs(state.records) do render(record) end
        if type(env.writefile)=="function" then pcall(env.writefile,"0xseanlee-ui-language.txt",language) end
        return true
    end
    function state.stop()
        state.active=false
        for _,connection in ipairs(state.connections) do pcall(function() connection:Disconnect() end) end
    end
    local function pack(...) return {n=select("#",...),...} end
    local unpackValues=unpack or table.unpack
    local function decorateControl(control,lib)
        if type(control)~="table" then return control end
        for _,name in ipairs({"Set","Add","Remove","SetTitle","SetDesc"}) do
            local original=rawget(control,name)
            if type(original)=="function" then
                control[name]=function(self,...)
                    local results=pack(original(self,...));state.scan(lib)
                    return unpackValues(results,1,results.n)
                end
            end
        end
        return control
    end
    local function decorateTab(tab,lib,title)
        for _,name in ipairs({"AddSection","AddParagraph","AddButton","AddToggle","AddDropdown","AddSlider"}) do
            local original=tab[name]
            if type(original)=="function" then
                tab[name]=function(self,config,...)
                    if name=="AddParagraph" and type(config)=="table" and config.Content and not config.Text and not config[2] then
                        local copy={};for k,v in pairs(config) do copy[k]=v end
                        copy.Text=config.Content;config=copy
                    end
                    local results=pack(original(self,config,...))
                    decorateControl(results[1],lib);state.scan(lib)
                    return unpackValues(results,1,results.n)
                end
            end
        end
        if title=="Settings" then
            tab:AddSection({"Interface"})
            tab:AddDropdown({Name="UI language",Description="Choose your interface language.",
                Options={"繁體中文","English"},Default=state.language=="en" and "English" or "繁體中文",
                Callback=function(value) state.setLanguage(value) end})
        end
    end
    function state.wrapLibrary(lib)
        if type(lib)~="table" or type(rawget(lib,"MakeWindow"))~="function" then return lib end
        if rawget(lib,"__0xseanleeLocalized") then return lib end
        lib.__0xseanleeLocalized=true
        local original=lib.MakeWindow
        lib.MakeWindow=function(self,config,...)
            local branded={};for k,v in pairs(config or {}) do branded[k]=v end
            branded[1]=nil;branded[2]=nil;branded.Name=nil
            branded.Title="0xseanlee Hub";branded.SubTitle="by 0xseanlee"
            local window=original(self,branded,...)
            local makeTab=window.MakeTab
            window.MakeTab=function(self,first,second,...)
                local cfg=type(first)=="table" and first or second
                local title=type(cfg)=="table" and (cfg[1] or cfg.Title) or ""
                local tab=makeTab(self,first,second,...)
                decorateTab(tab,lib,title);state.scan(lib)
                return tab
            end
            local info=window:MakeTab({"Info","info"})
            info:AddParagraph({Title="Creator",Text="0xseanlee"})
            info:AddParagraph({Title="Discord",Text="https://0xseanlee.me/discord"})
            info:AddParagraph({Title="",Text="Join the community using the link below."})
            info:AddButton({Title="Copy Discord Link",Callback=function()
                local clipboard=env.setclipboard or env.toclipboard
                if type(clipboard)=="function" then
                    local ok=pcall(clipboard,"https://0xseanlee.me/discord")
                    if ok then return end
                end
                if type(env.warn)=="function" then env.warn("Discord: https://0xseanlee.me/discord") end
            end})
            state.scan(lib)
            return window
        end
        state.scan(lib)
        return lib
    end
    -- Only this chunk's UI loader key changes; gameplay constants are never translated.
    assert(pool[1].constants[89]=="loadstring","Unexpected UI loader constant")
    pool[1].constants[89]="__MoonSecUILoad"
    local load=env.loadstring
    env.__MoonSecUILoad=function(...)
        local compiled,reason=load(...)
        if not compiled then return nil,reason end
        return function(...)
            local values=pack(compiled(...))
            values[1]=state.wrapLibrary(values[1])
            return unpackValues(values,1,values.n)
        end
    end
    env.__MoonSecUI=state
    if type(env.getgenv)=="function" then
        local ok,shared=pcall(env.getgenv)
        if ok and type(shared)=="table" then shared.__MoonSecUI=state end
    end
    return state
end

-- One bounded farm step per existing worker tick, with quest acknowledgement state.
local function installQuestControllers(pool, env)
    local function child(parent, name)
        if parent == nil then return nil end
        local ok,value=pcall(function() return parent:FindFirstChild(name) end)
        if ok then return value end
    end
    local function normalize(value)
        return tostring(value or ""):lower():gsub("<[^>]*>",""):gsub("%[.-%]",""):gsub("[%s%p]","")
    end
    local function clock() return (env.tick or os.clock)() end
    local function readQuestHud(player)
        local playerGui=child(player,"PlayerGui")
        if playerGui==nil then return nil end
        -- Current client: the visible tracker is independent of the old Main.Quest template.
        local tracked=child(playerGui,"TrackedQuestFrame")
        local frame=child(tracked,"Frame")
        if frame and tracked.Enabled~=false and frame.Visible==true then
            local label=child(child(frame,"header"),"textLabel")
            local description=child(frame,"description")
            local title=label and label.Text or ""
            local detail=description and description.Text or ""
            if title~="" or detail~="" then
                return {active=true,title=title,description=detail,source="TrackedQuestFrame"}
            end
        end
        local main=child(playerGui,"Main")
        local legacy=child(main,"Quest")
        if legacy then
            local label=child(child(child(legacy,"Container"),"QuestTitle"),"Title")
            return {active=main.Enabled~=false and legacy.Visible==true,title=label and label.Text or "",
                description="",source="Main.Quest"}
        end
        if tracked then return {active=false,title="",description="",source="TrackedQuestFrame"} end
        return nil
    end
    local function create(newIsland)
        local s={phase="idle", lastTick=-100, lastStart=-100, lastAbandon=-100, lastMove=-100, lastCombat=-100}
        local function enabled() return env._G[newIsland and "AutoFarmLevelNew" or "AutoFarm"] end
        local function target()
            local suffix=newIsland and "New" or ""
            local check=env["CheckQuest"..suffix]
            if type(check)~="function" then return nil end
            check()
            local q={quest=env["NameQuest"..suffix],level=env["LevelQuest"..suffix],monster=env["Mon"..suffix],
                name=env["NameMon"..suffix],questPosition=env["CFrameQuest"..suffix],spawnPosition=env["CFrameMon"..suffix]}
            if type(q.quest)~="string" or type(q.level)~="number" or type(q.monster)~="string" or q.questPosition==nil then return nil end
            q.key=q.quest..":"..q.level
            return q
        end
        local function matches(title,q)
            local value=normalize(title)
            for _,name in ipairs({q.name or "",q.monster}) do
                local key=normalize(name)
                if #key>0 and string.find(value,key,1,true) then return true end
            end
            return false
        end
        local function move(position,now)
            if position~=nil and now-s.lastMove>=0.35 then
                s.lastMove=now
                local fn=env.TP1 or env.topos
                if type(fn)=="function" then fn(position) end
            end
        end
        local function invoke(command,...)
            local storage=env.game:GetService("ReplicatedStorage")
            local remote=child(child(storage,"Remotes"),"CommF_")
            if remote==nil then s.phase="waiting_remote"; return false end
            local ok,result=pcall(remote.InvokeServer,remote,command,...)
            if not ok then
                local diag=env.__MoonSecDiag
                if type(diag)=="table" and type(diag.capture)=="function" then pcall(diag.capture,"quest",result) end
            end
            return ok,result
        end
        function s.step()
            local now=clock()
            if now-s.lastTick<0.12 or s.busy then return end
            s.lastTick=now
            if not enabled() then s.phase="idle";s.accepted=nil;s.requested=nil;return end
            local player=env.game:GetService("Players").LocalPlayer
            local character=player and player.Character
            local root=child(character,"HumanoidRootPart")
            local humanoid=child(character,"Humanoid")
            if root==nil or humanoid==nil or humanoid.Health<=0 then s.phase="waiting_character";return end
            local quest=readQuestHud(player)
            if quest==nil then s.phase="waiting_quest_ui";return end
            s.hudSource=quest.source;s.questTitle=quest.title
            local current=target()
            if current==nil then s.phase="waiting_target";return end
            local active=quest.active
            if not active then
                env.StartBring=false
                s.accepted=nil;s.mismatchAt=nil
                if now-s.lastStart<4 then s.phase="awaiting_quest";return end
                local distance=(root.Position-current.questPosition.Position).Magnitude
                if distance>20 then s.phase="travelling_quest";move(current.questPosition,now);return end
                s.busy=true;s.lastStart=now;s.requested=current;s.phase="requesting_quest"
                local ok=invoke("StartQuest",current.quest,current.level)
                s.busy=false
                s.phase=ok and "awaiting_quest" or "quest_request_failed"
                if not ok then s.requested=nil end
                return
            end
            local title=quest.title
            -- Visibility after our request confirms acceptance even for translated game titles.
            if s.requested then s.accepted=s.requested;s.requested=nil end
            if not s.accepted then
                if matches(title,current) or matches(quest.description,current) then
                    s.accepted=current;s.mismatchAt=nil
                elseif title=="" then
                    s.phase="awaiting_quest_title";return
                elseif string.find(title,"[\128-\255]") then
                    -- A pre-existing localized quest is not evidence of a mismatched quest.
                    s.accepted=current
                else
                    if s.mismatchTitle~=title or s.mismatchKey~=current.key then
                        s.mismatchTitle=title;s.mismatchKey=current.key;s.mismatchAt=now
                    end
                    s.phase="checking_existing_quest"
                    if now-s.mismatchAt>=2.5 and now-s.lastAbandon>=4 then
                        s.lastAbandon=now;s.busy=true
                        invoke("AbandonQuest")
                        s.busy=false;s.phase="resetting_wrong_quest";s.lastStart=now
                    end
                    return
                end
            end
            local q=s.accepted
            local enemies=child(env.game:GetService("Workspace"),"Enemies")
            local nearest,nearestRoot,nearestHumanoid,best=nil,nil,nil,math.huge
            if enemies then
                for _,enemy in ipairs(enemies:GetChildren()) do
                    local enemyRoot=child(enemy,"HumanoidRootPart")
                    local enemyHumanoid=child(enemy,"Humanoid")
                    if enemyRoot and enemyHumanoid and enemyHumanoid.Health>0 and normalize(enemy.Name)==normalize(q.monster) then
                        local distance=(root.Position-enemyRoot.Position).Magnitude
                        if distance<best then nearest,nearestRoot,nearestHumanoid,best=enemy,enemyRoot,enemyHumanoid,distance end
                    end
                end
            end
            if not nearest then
                env.StartBring=false;s.phase="awaiting_spawn";move(q.spawnPosition,now);return
            end
            s.phase="combat"
            env.StartBring=true
            env[newIsland and "MonFarmNew" or "MonFarm"]=nearest.Name
            env.PosMon=nearestRoot.CFrame
            if now-s.lastCombat>=0.35 then
                s.lastCombat=now
                if type(env.EquipWeapon)=="function" then env.EquipWeapon(env._G.SelectWeapon) end
                if type(env.AutoHaki)=="function" then env.AutoHaki() end
                local mover=env.topos or env.TP1
                if type(mover)=="function" then mover(nearestRoot.CFrame*env.CFrame.new(0,30,0)) end
                nearestRoot.CanCollide=false;nearestHumanoid.WalkSpeed=0
                local head=child(nearest,"Head");if head then head.CanCollide=false end
                local user=env.game:GetService("VirtualUser")
                user:CaptureController();user:Button1Down(env.Vector2.new(1280,672))
            end
        end
        return s
    end
    local controllers={normal=create(false),newIsland=create(true)}
    env.__MoonSecFarm=controllers
    if type(env.getgenv)=="function" then
        local ok,shared=pcall(env.getgenv)
        if ok and type(shared)=="table" then shared.__MoonSecFarm=controllers end
    end
    local function run(controller)
        local ok,reason=pcall(controller.step)
        if not ok then
            controller.busy=false;controller.phase="error";controller.lastError=tostring(reason)
            local diag=env.__MoonSecDiag
            if type(diag)=="table" and type(diag.capture)=="function" then pcall(diag.capture,"quest",controller.lastError) end
            local now=clock()
            if type(env.warn)=="function" and (controller.lastReportedError~=controller.lastError or now-(controller.lastReportedAt or -100)>=5) then
                controller.lastReportedError=controller.lastError;controller.lastReportedAt=now
                env.warn("[MoonSecFarm] "..controller.lastError)
            end
        end
    end
    for _,proto in ipairs(pool) do
        if proto.path=="0_203" then
            proto.native=function(current,enabled)
                if enabled then return end
                current._G.StopTween=true
                pcall(function()
                    local waitFor=current.wait or (current.task and current.task.wait)
                    if type(waitFor)=="function" then waitFor() end
                    local player=current.game:GetService("Players").LocalPlayer
                    local root=player and child(player.Character,"HumanoidRootPart")
                    if root==nil then return end
                    if type(current.topos)=="function" then current.topos(root.CFrame) end
                    if type(waitFor)=="function" then waitFor() end
                    root=player and child(player.Character,"HumanoidRootPart")
                    local clip=child(root,"BodyClip")
                    if clip then clip:Destroy() end
                end)
                current._G.StopTween=false;current._G.Clip=false
            end
        end
        if proto.path=="0_453" then
            proto.precondition=function(current)
                local player=current.game:GetService("Players").LocalPlayer
                return player~=nil and player.Character~=nil
            end
        end
        if proto.path=="0_264_0" then proto.native=function() return run(controllers.normal) end end
        if proto.path=="0_89_0" then proto.native=function() return run(controllers.newIsland) end end
        if proto.path=="0_69_0" then
            proto.precondition=function(current)
                local player=current.game:GetService("Players").LocalPlayer
                current.plr=player
                return player~=nil and child(player.Character,"Head")~=nil
            end
        end
        if proto.path=="0_18_0" then
            -- Guard only the observed optional BodyClip cleanup, keeping existing jump PCs.
            local code=proto.code
            assert(code[(438-1)*4+1]==11 and code[(440-1)*4+1]==30,"Unexpected cleanup prototype")
            local original={code[(438-1)*4+1],code[(438-1)*4+2],code[(438-1)*4+3],code[(438-1)*4+4]}
            code[(438-1)*4+1],code[(438-1)*4+2],code[(438-1)*4+3],code[(438-1)*4+4]=22,0,256,1
            local extra={26,0,0,0,22,0,256,2,original[1],original[2],original[3],original[4],28,0,2,1,30,0,1,0,30,0,1,0}
            for _,value in ipairs(extra) do code[#code+1]=value end
        end
    end
    return controllers
end

