-- User-provided PNG is embedded so the icon does not depend on CDN availability at runtime.
local function installHubIcon(pool,env,png)
    local state={
        source="https://cdn.discordapp.com/icons/1135164370305953802/2076580a7a90bee924cd6537141bac5d.png?size=2048",
        file="0xseanlee-hub-icon-2076580a7a90bee924cd6537141bac5d.png",loaded=false,
    }
    local asset=env.getcustomasset or env.getsynasset
    if type(asset)=="function" and type(env.writefile)=="function" then
        local ok,reason=pcall(function()
            env.writefile(state.file,png)
            local content=asset(state.file)
            assert(type(content)=="string" and content~="","Custom asset loader returned no image")
            state.content=content;state.loaded=true
        end)
        if not ok then state.reason=tostring(reason) end
    else
        state.reason="The executor needs writefile and getcustomasset/getsynasset to display this PNG."
    end
    local replaced=0
    for _,proto in ipairs(pool) do
        for index,value in pairs(proto.constants) do
            if value=="rbxassetid://80424431930361" then
                proto.constants[index]=state.content or ""
                replaced=replaced+1
            end
        end
    end
    assert(replaced>0,"Original floating hub icon was not found")
    function state.finish()
        if state.loaded then return end
        -- A plain initials button keeps the hub accessible when local image APIs are absent.
        pcall(function()
            local gui=env.game:GetService("CoreGui"):FindFirstChild("ControlGUI")
            local button=gui and gui:FindFirstChild("ImageButton")
            if button==nil then return end
            local label=env.Instance.new("TextLabel")
            label.Name="0xseanleeIconFallback";label.Size=env.UDim2.new(1,0,1,0)
            label.Text="0x";label.TextScaled=true;label.Font=env.Enum.Font.GothamBold
            label.TextColor3=env.Color3.fromRGB(255,255,255);label.BackgroundColor3=env.Color3.fromRGB(24,29,33)
            label.BorderSizePixel=0;label.Parent=button
            local corner=env.Instance.new("UICorner")
            corner.CornerRadius=env.UDim.new(0.25,0);corner.Parent=label
        end)
    end
    env.__MoonSecHubIcon=state
    return state
end

-- Startup compatibility v2: Effect.Container moved to the sibling EffectContainer.
local environment = hostGetfenv and hostGetfenv() or _G
if environment.game == nil then
    error("This script requires a Roblox client executor.", 0)
end
if type(environment.loadstring) ~= "function" then
    error("The original UI dependency requires executor loadstring support.", 0)
end

local function startupNote(message)
    local text = "[MoonSec] " .. message
    local diag = environment.__MoonSecDiag
    if type(diag) == "table" and type(diag.capture) == "function" then
        pcall(diag.capture, "startup", text)
    end
    if type(environment.warn) == "function" then environment.warn(text) end
end

local function findChild(parent, name)
    if parent == nil then return nil end
    local ok, child = pcall(function() return parent:FindFirstChild(name) end)
    if ok then return child end
end

local storage = environment.game:GetService("ReplicatedStorage")
local effect = findChild(storage, "Effect")
local legacyContainer = findChild(effect, "Container")
local currentContainer = findChild(storage, "EffectContainer")
for _,name in ipairs({"Death", "Respawn"}) do
    local module = findChild(legacyContainer, name) or findChild(currentContainer, name)
    if module == nil then
        startupNote("Optional " .. name .. " effect module unavailable; continuing startup.")
    elseif type(environment.hookfunction) ~= "function" then
        startupNote("hookfunction unavailable; leaving the optional " .. name .. " effect unchanged.")
    else
        local ok, reason = pcall(function()
            local target = environment.require(module)
            if type(target) ~= "function" then
                error("effect module returned " .. type(target), 0)
            end
            environment.hookfunction(target, function() end)
        end)
        if not ok then startupNote("Optional " .. name .. " effect hook failed: " .. tostring(reason)) end
    end
end

-- Only the two original unguarded effect hooks occupy instructions 1 through 24.
installLocalization(P,environment,UI_TRANSLATIONS)
installQuestControllers(P,environment)
local hubIcon=installHubIcon(P,environment,HUB_ICON_PNG)
P[1].entry = 25
local results=pack(makeClosure(P[1], {}, environment)(...))
hubIcon.finish()
return hostUnpack(results,1,results.n)
